import{b as a,O as e,g as s,j as n}from"./chunks/framework.DcaUmd3X.js";const u=JSON.parse('{"title":"压测场景设计","description":"","frontmatter":{},"headers":[],"relativePath":"performance/jmeter/scenarios/index.md","filePath":"性能测试/1.Jmeter/05.压测场景设计.md","lastUpdated":1781755252000}'),r={name:"performance/jmeter/scenarios/index.md"};function d(o,t,l,p,i,h){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="压测场景设计" tabindex="-1">压测场景设计 <a class="header-anchor" href="#压测场景设计" aria-label="Permalink to &quot;压测场景设计&quot;">​</a></h1><blockquote><p>压测不是线程数越大越好。从小开始、逐步加压、找到拐点，才是正确的姿势。</p></blockquote><h2 id="四级递进法" tabindex="-1">四级递进法 <a class="header-anchor" href="#四级递进法" aria-label="Permalink to &quot;四级递进法&quot;">​</a></h2><p>一次完整的压测，按四个档位递进。每档跑完看指标，没问题再升下一档。</p><table tabindex="0"><thead><tr><th>场景</th><th style="text-align:center;">线程</th><th>Ramp-Up</th><th>持续时间</th><th>目的</th></tr></thead><tbody><tr><td>🔬 基准测试</td><td style="text-align:center;">1</td><td>0s</td><td>循环 10 次</td><td>单用户单接口的响应时间，作为后续对比的参照线</td></tr><tr><td>🟢 轻度负载</td><td style="text-align:center;">10</td><td>5s</td><td>5 分钟</td><td>日常水位——系统在闲时应该轻松应对</td></tr><tr><td>🟡 中度负载</td><td style="text-align:center;">50</td><td>10s</td><td>10 分钟</td><td>业务高峰期——正常上限，各项指标不能明显劣化</td></tr><tr><td>🔴 重度压力</td><td style="text-align:center;">200</td><td>30s</td><td>30 分钟</td><td>找瓶颈——CPU 多高？内存多大？TPS 到多少开始报错？</td></tr></tbody></table><blockquote><p><strong>什么时候升档？</strong> 当前档位 Error% = 0、P95 响应时间无劣化，才升下一档。上一档就出错，先修系统。</p></blockquote><h2 id="阶梯加压" tabindex="-1">阶梯加压 <a class="header-anchor" href="#阶梯加压" aria-label="Permalink to &quot;阶梯加压&quot;">​</a></h2><p>标准线程组只能一次加到目标值。想看&quot;系统在多少人时开始崩&quot;，用阶梯式加压。</p><p>装完 Custom Thread Groups 插件后，用 <strong>Concurrency Thread Group</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标并发数：100</span></span>
<span class="line"><span>加速时间：5 分钟</span></span>
<span class="line"><span>加速步数：10 步</span></span>
<span class="line"><span>保持时间：10 分钟</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 每 30 秒增加 10 个用户，到 100 后保持 10 分钟</span></span></code></pre></div><p>关键观察：<strong>TPS 在哪个并发数不再增长？响应时间从哪一步开始飙升？</strong> 那个点就是系统的性能拐点。</p><h2 id="浪涌测试" tabindex="-1">浪涌测试 <a class="header-anchor" href="#浪涌测试" aria-label="Permalink to &quot;浪涌测试&quot;">​</a></h2><p>模拟突发流量——比如秒杀开始那一刻所有人同时点进来。</p><p>用 <strong>Ultimate Thread Group</strong> 定义多波次：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 波：50 人，0 秒开始，30 秒爬坡，持续 60 秒</span></span>
<span class="line"><span>第 2 波：100 人，60 秒开始，20 秒爬坡，持续 60 秒</span></span>
<span class="line"><span>第 3 波：200 人，120 秒开始，20 秒爬坡，持续 60 秒</span></span>
<span class="line"><span>第 4 波：300 人，180 秒开始，20 秒爬坡，持续 60 秒</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 一波没下去、下一波又来了，考验系统在浪涌叠加下的承压能力</span></span></code></pre></div><blockquote><p>浪涌测试非常暴力，建议从较低的起始线程数开始。别上来就打垮系统，没什么意义——要的是找到刚好快垮但还没垮的临界值。</p></blockquote><h2 id="稳定性测试" tabindex="-1">稳定性测试 <a class="header-anchor" href="#稳定性测试" aria-label="Permalink to &quot;稳定性测试&quot;">​</a></h2><p>系统在持续压力下会不会出现内存泄漏、连接池耗尽、日志撑爆磁盘？</p><table tabindex="0"><thead><tr><th>参数</th><th>建议值</th></tr></thead><tbody><tr><td>线程数</td><td>取中度负载的 70%~80%</td></tr><tr><td>持续时间</td><td><strong>至少 30 分钟</strong>，推荐 2~8 小时</td></tr><tr><td>观察重点</td><td>响应时间是否随时间缓慢上升？内存是否只增不减？</td></tr></tbody></table><blockquote><p>稳定性测试不追求高并发，追求长时间。很多问题短压测暴露不出来。</p></blockquote><h2 id="场景设计清单" tabindex="-1">场景设计清单 <a class="header-anchor" href="#场景设计清单" aria-label="Permalink to &quot;场景设计清单&quot;">​</a></h2><p>动手前先想清楚这四个问题：</p><table tabindex="0"><thead><tr><th>问题</th><th>示例</th></tr></thead><tbody><tr><td><strong>测什么接口？</strong></td><td>登录、商品列表、创建订单、用户信息</td></tr><tr><td><strong>业务比例？</strong></td><td>80% 查商品 + 15% 下单 + 5% 查用户</td></tr><tr><td><strong>用户怎么来？</strong></td><td>10 秒内逐步启动 50 人，还是阶梯从 10 加到 100？</td></tr><tr><td><strong>跑多久？</strong></td><td>基准 10 次循环 / 压力 10 分钟 / 稳定性 2 小时</td></tr></tbody></table><p>前两个问题决定了脚本结构（用吞吐量控制器分配比例），后两个决定了线程组参数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>四级递进</strong>：基准 → 轻度 → 中度 → 重度，逐档验证，不跳级</li><li><strong>阶梯加压</strong>：用 Concurrency Thread Group 找性能拐点</li><li><strong>浪涌测试</strong>：用 Ultimate Thread Group 模拟突发流量</li><li><strong>稳定性测试</strong>：长时间跑，看内存泄漏和资源累积问题</li><li><strong>动手前先列清单</strong>：测什么、比例多少、怎么加压、跑多久</li></ul>`,26)])])}const b=a(r,[["render",d]]);export{u as __pageData,b as default};
